import sys

def main():
    data = sys.stdin.readline().strip()
    if not data:
        return
    s = data.split()[0]
    if s.startswith('-'):
        s = s[1:]

    evens = []
    odds = []
    for ch in s:
        if ch.isdigit():
            if int(ch) % 2 == 0:
                evens.append(ch)
            else:
                odds.append(ch)

    print(' '.join(evens))
    print(' '.join(odds))

if __name__ == '__main__':
    main()
